require_once __DIR__.'/includes/functions.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);require '404.php';exit;}$s=db()->prepare('SELECT p.*,c.category_name,(SELECT AVG(rating) FROM reviews WHERE product_id=p.id AND status="approved") rating,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);require '404.php';exit;}customer_recently_viewed($id);$price=product_price($id,(float)$p['price']);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($p['stock']>0){$_SESSION['cart'][$id]=(int)($_SESSION['cart'][$id]??0)+1;flash('success','Phone added to cart.');}header('Location: cart.php');exit;}$i=db()->prepare('SELECT image_path FROM product_images WHERE product_id=? ORDER BY id');$i->execute([$id]);$images=$i->fetchAll(PDO::FETCH_COLUMN)?:[null];$colors=colors_for($id);$r=db()->prepare('SELECT * FROM reviews WHERE product_id=? AND status="approved" ORDER BY created_at DESC');$r->execute([$id]);$reviews=$r->fetchAll();$related=db()->prepare('SELECT p.id,p.name,p.brand,p.price,p.stock,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image FROM products p WHERE p.id<>? AND (p.brand=? OR p.category_id=? OR p.price BETWEEN ? AND ?) ORDER BY (p.brand=?) DESC, ABS(p.price-?) LIMIT 4');$related->execute([$id,$p['brand'],$p['category_id'],(float)$p['price']*.75,(float)$p['price']*1.25,$p['brand'],(float)$p['price']]);$related=$related->fetchAll();$page_title=$p['name'];require 'includes/header.php';
?><section class="section"><div class="container"><a class="back-link" href="index.php#shop">← Back to phones</a><div class="details-grid"><div class="gallery"><img id="main-image" src="<?=image_url($images[0])?>" alt="<?=e($p['name'])?>"><?php if(count($images)>1):?><div class="thumbnails"><?php foreach($images as $image):?><button type="button" data-image="<?=image_url($image)?>"><img src="<?=image_url($image)?>" alt="<?=e($p['name'])?>"></button><?php endforeach?></div><?php endif?></div><div><span class="badge <?=strtolower($p['brand'])?>"><?=e($p['brand'])?></span><h1 class="product-title"><?=e($p['name'])?></h1><div class="rating"><?=$p['rating']?number_format((float)$p['rating'],1).' / 5':'No reviews yet'?></div><p class="price"><?=money($price)?><?php if($price<(float)$p['price']):?> <del><?=money($p['price'])?></del><?php endif?></p><p class="stock <?=$p['stock']>0?'in':'out'?>"><i class="fa-solid fa-circle"></i> <?=$p['stock']>0?$p['stock'].' available':'Currently out of stock'?></p><dl class="spec-list"><div><dt>Storage</dt><dd><?=e($p['storage'])?></dd></div><div><dt>Condition</dt><dd><?=e($p['condition'])?></dd></div><div><dt>Quality</dt><dd><?=e($p['quality'])?></dd></div><?php if($colors):?><div><dt>Colours</dt><dd><?=e(implode(', ',$colors))?></dd></div><?php endif?></dl><p><?=nl2br(e($p['description']))?></p><button class="wishlist-toggle detail-wishlist" type="button" data-product-id="<?=$id?>" aria-label="Save <?=e($p['name'])?> to wishlist">♡ Save to wishlist</button><div class="bnpl-note"><strong>Instalment payments</strong><p>Not available at checkout yet. Collins M has not connected a BNPL merchant account, so no financing or payment is being offered.</p></div><div class="details-actions"><?php if($p['stock']>0):?><form method="post" class="inline-cart"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="button primary"><i class="fa-solid fa-cart-plus"></i> Add to cart</button></form><?php endif?><a class="button whatsapp" target="_blank" rel="noopener" href="<?=e(whatsapp_url())?>"><i class="fa-brands fa-whatsapp"></i> Ask on WhatsApp</a></div></div></div><section class="specs"><h2>Technical specifications</h2><p><?=nl2br(e($p['specifications']?:'Contact us for full specifications.'))?></p></section><?php if($related):?><section class="related-products"><div class="section-title"><div><p class="eyebrow">Picked for you</p><h2>YOU MAY ALSO LIKE</h2></div></div><div class="products-grid"><?php foreach($related as $rp):?><article class="product-card"><a class="product-image" href="product-details.php?id=<?=$rp['id']?>"><img loading="lazy" src="<?=image_url($rp['image'])?>" alt="<?=e($rp['brand'].' '.$rp['name'])?>"></a><div class="product-info"><span class="badge <?=strtolower($rp['brand'])?>"><?=e($rp['brand'])?></span><button class="wishlist-toggle" type="button" data-product-id="<?=$rp['id']?>" aria-label="Save <?=e($rp['name'])?>">♡</button><h3><?=e($rp['name'])?></h3><strong><?=money(product_price((int)$rp['id'],(float)$rp['price']))?></strong><span class="stock <?=$rp['stock']?'in':'out'?>"><?=$rp['stock']?'In stock':'Out of stock'?></span><a class="button dark-button" href="product-details.php?id=<?=$rp['id']?>">View product</a></div></article><?php endforeach?></div></section><?php endif?><section class="reviews"><h2>Customer reviews</h2><?php foreach($reviews as $review):?><article><strong><?=e($review['customer_name'])?></strong><p><?=e($review['comment'])?></p></article><?php endforeach?><form class="review-form" method="post" action="reviews/submit-review.php"><h3>Leave a review</h3><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$id?>"><input required name="customer_name" maxlength="80" placeholder="Your name"><select required name="rating"><option value="">Your rating</option><?php for($x=5;$x>=1;$x--):?><option value="<?=$x?>"><?=$x?> stars</option><?php endfor?></select><textarea required name="comment" maxlength="1000" placeholder="Tell us about your experience"></textarea><button class="button primary">Submit review</button></form></section></div></section><script>window.collinsProduct={id:<?=json_encode((int)$id)?>,name:<?=json_encode($p['name'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,price:<?=json_encode(money($price),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,image:<?=json_encode(image_url($p['image']),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,url:<?=json_encode('product-details.php?id='.$id,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>};</script><?php require 'includes/footer.php';?>
